mapper.select:
select * from ( with t2 as (select a.sppi_test_id as sppiTestId, t1.finprod_id as finprodId, t1.FINPROD_MARKET_ID as finprodMarketId, t1.finprodName, t1.assetType, --优先取标的表中的SPPI测试状态 case when nvl(t1.sppi_test_status, '0') = '0' and a.test_status = '1' then '1' when nvl(t1.sppi_test_status, '0') = '0' then '0' else t1.sppi_test_status end as testStatus,
--更新人及更新时间以标的表中的为准 case --测试状态都没有，则没有更新人、更新时间 when nvl(t1.sppi_test_status, '0') = '0' and a.test_status is null then null --标的表中没有测试状态（审核中），则取SPPI测试记录主表中的更新人、更新时间 when nvl(t1.sppi_test_status, '0') = '0' and a.test_status is not null then a.update_user --其它情况就是标的表中有测试状态;不存在标的表中有，而SPPI测试记录主表中无测试状态的情况 else t1.update_user end as updateUser,
case when nvl(t1.sppi_test_status, '0') = '0' and a.test_status is null then null when nvl(t1.sppi_test_status, '0') = '0' and a.test_status is not null then a.update_time else t1.update_time end as notInitUpdateTime, a.sppi_tmp_type as sppiTmpType, a.sppi_tmp_no as sppiTmpNo from (select f.finprod_id, f.FINPROD_MARKET_ID, nvl(f.finprod_abbr, f.finprod_name) as finprodName, t.type_8 as assetType, f.update_time, f.update_user, f.sppi_test_status from fin_product f, fin_product_type t where f.finprod_id = t.finprod_id
and f.finprod_id in
#{item}
and t.type_8 = #{assetType,jdbcType=VARCHAR}
/*add by czj 20210531 增加一级市场债*/ and t.type_8 IN ('F01', 'F06', 'F03','F17')
) t1 left join (select x.*, row_number() over (partition BY x.finprod_id order by x.update_time DESC) as rowno from sppi_test x) a on t1.finprod_id = a.finprod_id and a.rowno = 1) select t2.*, u.real_name as updateUserName,'内部评估' dataSource from t2 left join sys_user u on t2.updateUser = u.user_name where not exists( select 1 from SPPI_IMPORT_DATA where BOND_ID = t2.finprodId )
and t2.testStatus = #{testStatus,jdbcType=VARCHAR}
UNION ALL
SELECT '' sppiTestId, sid.BOND_ID finprodId, fp.FINPROD_MARKET_ID finprodMarketId, sid.BOND_ABBR finprodName, fpt.type_8 assetType, sid.IS_SPPI_PASS testStatus, sid.update_user updateUser, sid.IMPORT_DATE notInitUpdateTime, '' sppiTmpType, '' sppiTmpNo, '' updateUserName, '中债' dataSource FROM SPPI_IMPORT_DATA sid left join fin_product fp on sid.BOND_ID = fp.finprod_id LEFT JOIN fin_product_type fpt on sid.BOND_ID = fpt.finprod_id where 1=1
and sid.IS_SPPI_PASS = #{testStatus,jdbcType=VARCHAR}
and sid.BOND_ID in
#{item}
and fpt.type_8 = #{assetType,jdbcType=VARCHAR}
/*add by czj 20210531 增加一级市场债*/ and fpt.type_8 IN ('F01', 'F06', 'F03','F17')
)

mapper.insert:
insert into SPPI_TEST_QA (SPPI_TEST_ID, FINPROD_ID, QUESTION_NO, ANSWER_TYPE, ANSWER_VALUE, REMARK, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select A.* from (
select #{item.sppiTestId,jdbcType=VARCHAR}, #{item.finprodId,jdbcType=VARCHAR}, #{item.questionNo,jdbcType=VARCHAR}, #{item.answerType,jdbcType=CHAR}, #{item.answerValue,jdbcType=VARCHAR}, #{item.remark,jdbcType=VARCHAR}, #{item.createUser,jdbcType=VARCHAR}, #{item.createDept,jdbcType=VARCHAR}, #{item.createTime,jdbcType=TIMESTAMP}, #{item.updateUser,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=TIMESTAMP} from dual
) A

